import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  const stmt = db.prepare('SELECT 9007199254740993 AS big, 42 AS small');
  try { stmt.get(); } catch (e: any) { console.log(e.name, e.code, e.message); }
  stmt.setReadBigInts(true);
  console.log(String(stmt.get().big), typeof stmt.get().big, String(stmt.get().small), typeof stmt.get().small);
  const echo = db.prepare('SELECT ? AS v');
  echo.setReadBigInts(true);
  db.close();
}
